130	  // this function, `eligibility` and `missingCategory` can never disagree about
131	  // what the closet can do. Ordering in-season-first matters because the CAP
132	  // below truncates the combo list, and the breadth-first walk indexes outerwear
133	  // and accessories modulo their list length — so the earliest passes reach the
134	  // seasonally right coat and accessory.
135	  const by = eligibleByCategory(items, a);
136	  const tops = by.Tops ?? [];
137	  const bottoms = by.Bottoms ?? [];
138	  const shoes = by.Shoes ?? [];
139	  const outer = by.Outerwear ?? [];
140	  const accessories = by.Accessories ?? [];
141	
142	  // A combo needs all three required slots; without one there is nothing to build.
143	  if (!tops.length || !bottoms.length || !shoes.length) return [];
144	
145	  const combos: CandidateItem[][] = [];
146	
147	  // BREADTH-FIRST, not a nested product.
148	  //
149	  // This used to be three nested loops followed by `.slice(0, CAP)`. Because the
150	  // loops were top-major, every combination of the FIRST top was generated
151	  // before the second top was reached — so the cap was spent inside one top. A
152	  // closet with 20 of each category reached 1 top and 5 bottoms out of 20, which
153	  // is both reported symptoms at once: most of the wardrobe invisible to
154	  // ranking, and every look sharing a garment because there was only one to
155	  // share. Small closets stayed under the cap, which is why tests never saw it.
156	  //
157	  // Each pass `d` walks all tops once, pairing each with a different bottom and
158	  // shoe, so pass 0 alone touches every top, bottom and shoe. Later passes add
159	  // fresh pairings rather than exhausting one corner of the space. The offsets
160	  // are coprime-ish (d and 2d) so pairings do not repeat early.
161	  const passes = Math.max(bottoms.length, shoes.length);
162	
163	  build: for (let d = 0; d < passes; d++) {
164	    for (let t = 0; t < tops.length; t++) {
165	      const b = bottoms[(t + d) % bottoms.length];
166	      const s = shoes[(t + d * 2) % shoes.length];
167	
168	      // Outerwear is a PREFERENCE, not a requirement: layer it in when the cold
169	      // calls for it and the closet has one, but never refuse to dress someone
170	      // who owns no coat — that silently killed every outfit below 15°.
171	      // The weather strip's "Later" advice is what tells them to take a layer.
172	      // The index rotates too: it was pinned to [0], so one coat was worn on
173	      // every cold day and every other coat was unreachable.
174	      const base =
175	        needsOuterwear && outer.length
176	          ? [tops[t], b, s, outer[(t + d) % outer.length]]
177	          : [tops[t], b, s];
178	
179	      combos.push(base); // required base (± outerwear), no accessory
180	      if (combos.length >= CAP) break build;
181	
182	      if (a.maxAccessories > 0 && accessories.length) {
183	        combos.push([...base, accessories[(t + d) % accessories.length]]); // optional, capped accent
184	        if (combos.length >= CAP) break build;
185	      }
186	    }
187	  }
188	
189	  // Colour is deliberately NOT filtered here. The Refine palette is a lean, and
190	  // leans are expressed by ranking (`scoreCombo`'s lean term), not by exclusion —
191	  // the same soft-preference model outerwear moved to above.
192	  return combos;
193	}
